WITH exploded AS (SELECT id, service, host, log_ts, level, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, v) SELECT CASE WHEN status_code >= 470 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, SORT_ARRAY(COLLECT_SET(k)) AS k_list, SORT_ARRAY(COLLECT_SET(level)) AS level_list, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN service = 'search' THEN 1 END), 0), 2) AS status_code_per_search, SORT_ARRAY(COLLECT_SET(k)) AS k_list_2, PERCENTILE_APPROX(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles FROM exploded GROUP BY CASE WHEN status_code >= 470 THEN 'HIGH' ELSE 'LOW' END HAVING (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 >= 0
